import "std/text.ouro";
import "std/cli.ouro";
def keep (x : Nat) : Nat := x;

def pick (a : Nat) (b : Nat) : Nat :=
  match a with
  | Z => match b with | Z => 1 | S _ => 0 end
  | S _ => match b with | Z => 2 | S _ => 0 end
  end;

def load (p : String) : Either FsError String :=
  match fs_read_checked p with
  | Left e => Left FsError String e
  | Right text => Right FsError String text
  end;

def main (args : Args) : Either CliError String :=
  match cli_required args "path" with
  | Left e => Left CliError String (CliUsage (cli_error_message e))
  | Right p => Right CliError String p
  end;

inductive Rec : Type := | MkRec : Nat -> Nat -> Rec;
def rec_left (r : Rec) : Nat := match r with | MkRec a b => a end;
def rec_right (r : Rec) : Nat := match r with | MkRec a b => b end;
